@page "/settings"
@rendermode InteractiveServer
@using sv_175a7db667d04deab0176c36741a1158.Services
@implements IDisposable
@inject ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 500px; border-color: @ThemeSvc.AccentColor;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button class="btn @(ThemeSvc.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                    style="@(ThemeSvc.Theme == mode ? $"background-color:{ThemeSvc.AccentColor};border-color:{ThemeSvc.AccentColor};" : "")"
                    @onclick="() => ThemeSvc.Theme = mode">
                @mode
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-3 mb-3">
        <input type="color" class="form-control form-control-color"
               value="@ThemeSvc.AccentColor"
               @onchange="OnColorChanged" />
        <span>@ThemeSvc.AccentColor</span>
    </div>

    <p class="text-muted mt-3">
        Changes are applied immediately to all components across the app.
    </p>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

